"""Фигурный раскрой CAM. Закройте CAM, положите установщик рядом с app.py."""
import ast,base64,hashlib,json,os,tempfile,zlib
from pathlib import Path
from datetime import datetime
DATA=(
 ''
)
DIGEST='8861b699c3aca1f346fbc7da3f3e67e5f7ea10bf6fbb0babe4ce71fe548222c0'
def setup():
    folder=Path(__file__).resolve().parent
    required=('app.py','nesting.py','nesting_batch.py','nesting_editor.py','motion_preview.py','hold_down.py','start_points.py','project.py')
    missing=[n for n in required if not (folder/n).is_file()]
    if missing:raise ValueError('Положите установщик в папку CAM рядом с app.py. Не найдены: '+', '.join(missing))
    raw=zlib.decompress(base64.b64decode(DATA,validate=True))
    if hashlib.sha256(raw).hexdigest()!=DIGEST:raise ValueError('Установщик повреждён или скопирован не полностью')
    payload=json.loads(raw);sources={'figure_nesting.py':payload['module']}
    for name,patches in payload['patches'].items():
        text=(folder/name).read_text(encoding='utf-8-sig')
        for old,new in patches:
            if text.count(new)==1 and old not in text:continue
            if text.count(old)!=1:raise ValueError('Неподдерживаемая версия '+name+'. Файлы не изменены.')
            text=text.replace(old,new)
        sources[name]=text
    text=(folder/'app.py').read_text(encoding='utf-8-sig');lines=text.splitlines(keepends=True);remove=set()
    for node in ast.parse(text).body:
        known=isinstance(node,ast.Import) and len(node.names)==1 and node.names[0].name=='figure_nesting' and node.names[0].asname is None
        call=isinstance(node,ast.Expr) and isinstance(node.value,ast.Call) and ast.unparse(node.value)=='figure_nesting.install(Workbench)'
        if known or call:remove.update(range(node.lineno-1,node.end_lineno))
    text=''.join(line for i,line in enumerate(lines) if i not in remove);nodes=ast.parse(text).body;starts=[n for n in nodes if isinstance(n,ast.If) and ast.unparse(n.test)=="__name__ == '__main__'"]
    if len(starts)!=1 or not any(isinstance(n,ast.ClassDef) and n.name=='Workbench' for n in nodes):raise ValueError('Не найдена точка подключения CAM')
    lines=text.splitlines(keepends=True);lines.insert(starts[0].lineno-1,'import figure_nesting\nfigure_nesting.install(Workbench)\n');sources['app.py']=''.join(lines)
    for name,text in sources.items():compile(text,name,'exec')
    files={folder/name:text.encode('utf-8-sig' if name=='app.py' else 'utf-8') for name,text in sources.items()};old={p:p.read_bytes() if p.exists() else None for p in files};changes={p:b for p,b in files.items() if old[p]!=b}
    if not changes:print('Фигурный раскрой уже обновлён.');return
    backup=folder/('backup-figure-nesting-'+datetime.now().strftime('%Y%m%d-%H%M%S-%f'));backup.mkdir()
    for p in changes:
        if old[p] is not None:(backup/p.name).write_bytes(old[p])
    temps=[];written=[]
    try:
        for p,b in changes.items():
            with tempfile.NamedTemporaryFile('wb',dir=folder,delete=False) as f:
                temp=Path(f.name);temps.append((p,temp));f.write(b);f.flush();os.fsync(f.fileno())
        for p,temp in temps:os.replace(temp,p);written.append(p)
    except BaseException:
        for p in reversed(written):
            if old[p] is None:p.unlink(missing_ok=True)
            else:p.write_bytes(old[p])
        raise
    finally:
        for p,temp in temps:temp.unlink(missing_ok=True)
    print('Готово. Перезапустите CAM. Откройте «Раскрой → Настройки → Фигурный раскрой». Выберите нужный шаг поворота и нажмите «Рассчитать». Резервная копия:',backup.name)
if __name__=='__main__':
    try:setup()
    except Exception as exc:print('ОБНОВЛЕНИЕ НЕ УСТАНОВЛЕНО:',exc)
    input('Нажмите Enter для закрытия...')
